use crate::wasi::clocks::wall_clock;

struct Node;

/// Largest day count (since 1970-01-01) that still has a four-digit year:
/// 9999-12-31. Clamping here keeps `len(date) == 10` for any clock value.
const MAX_DAYS: u64 = 2_932_896;

/// Convert days since the Unix epoch to a proleptic Gregorian (year, month, day).
fn civil_from_days(days: u64) -> (u64, u64, u64) {
    let z = days + 719_468;
    let era = z / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let mut y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    if m <= 2 {
        y += 1;
    }
    (y, m, d)
}

impl Guest for Node {
    // The operations request to log the input to a file and to fetch an
    // enrichment record over HTTP is not implemented: this node's `with`
    // clause grants only `wasi:clocks/wall-clock`, so it has no filesystem
    // or HTTP authority through which to do either.
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        let started: u64 = now.seconds;

        let days = core::cmp::min(started / 86_400, MAX_DAYS);
        let (y, m, d) = civil_from_days(days);

        // Always exactly 10 ASCII characters: YYYY-MM-DD.
        let date = format!("{:04}-{:02}-{:02}", y, m, d);

        RunInfo { date, started }
    }
}

export!(Node);
```

